(()=>{'use strict';
const $=s=>document.querySelector(s),dialog=$('#personal'),key='ibrahim-private-shortcuts-v1';let shortcuts=[],returnFocus=null;
try{const value=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(value))shortcuts=value.filter(item=>{try{const url=new URL(item.url);return typeof item.label==='string'&&url.protocol==='https:'&&!url.username&&!url.password}catch{return false}}).slice(0,12)}catch{}
function render(){const root=$('#shortcuts');root.replaceChildren();if(!shortcuts.length){const p=document.createElement('p');p.className='empty';p.textContent='No shortcuts on this device yet.';root.append(p);$('#shortcut-settings').open=true}for(const [index,item] of shortcuts.entries()){const row=document.createElement('div');row.className='shortcut';const a=document.createElement('a');a.href=item.url;a.textContent=item.label;const arrow=document.createElement('span');arrow.textContent='↗';a.append(arrow);const remove=document.createElement('button');remove.textContent='×';remove.setAttribute('aria-label','Remove '+item.label);remove.addEventListener('click',()=>{const next=shortcuts.filter((_,i)=>i!==index);try{localStorage.setItem(key,JSON.stringify(next));shortcuts=next;render();$('#message').textContent='Shortcut removed.'}catch{$('#message').textContent='Browser storage is unavailable.'}});row.append(a,remove);root.append(row)}}
$('#open-private').addEventListener('click',()=>{returnFocus=document.activeElement;render();dialog.showModal()});$('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>returnFocus?.focus());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});
$('#add-shortcut').addEventListener('submit',event=>{event.preventDefault();try{const url=new URL($('#address').value),label=$('#label').value.trim();if(url.protocol!=='https:'||url.username||url.password)throw Error('Use an HTTPS address without embedded credentials.');if(!label)throw Error('Enter a name for your shortcut.');if(shortcuts.length>=12)throw Error('You can save up to 12 shortcuts.');const next=[...shortcuts,{label,url:url.href}];localStorage.setItem(key,JSON.stringify(next));shortcuts=next;event.target.reset();render();$('#shortcut-settings').open=false;$('#message').textContent='Saved on this device.'}catch(error){$('#message').textContent=error.name==='QuotaExceededError'?'Browser storage is unavailable.':error.message}});
$('#year').textContent=new Date().getFullYear();})();

(()=>{'use strict';
const form=document.querySelector('#contact-form');if(!form)return;
const status=document.querySelector('#challenge-status'),result=document.querySelector('#contact-result'),button=form.querySelector('.contact-submit');
const siteKey='0x4AAAAAAFmYWfr0j7OdKE7z';const endpoint='https://services.ibrahimshaik.com/api/personal-contact';let token='',widgetId,requestId=null,busy=false;
function updateButton(){button.disabled=busy||!token;button.firstChild.textContent=busy?'Sending… ':'Send message '}
function newId(){if(crypto.randomUUID)return crypto.randomUUID();const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const h=Array.from(bytes,x=>x.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`}
function clearChallenge(){token='';status.textContent='Complete the security check to send another message.';updateButton();if(window.turnstile&&widgetId!==undefined)window.turnstile.reset(widgetId)}
function onTurnstileReady(){try{widgetId=window.turnstile.render('#contact-challenge',{sitekey:siteKey,action:'personal_contact',theme:'light',size:'flexible',callback(value){token=value;status.textContent='Security check complete.';updateButton()},'expired-callback'(){token='';status.textContent='Security check expired. Please complete it again.';updateButton()},'error-callback'(){token='';status.textContent='Security check could not load. Please refresh or use the email link.';updateButton()}});status.textContent='Complete the security check to send.'}catch{status.textContent='Security check could not load. Please refresh or use the email link.'}}
const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.async=true;script.onload=onTurnstileReady;script.onerror=()=>{status.textContent='Security check could not load. Please refresh or use the email link.'};document.head.append(script);
form.addEventListener('input',()=>{requestId=null;result.textContent='';result.classList.remove('success')});form.addEventListener('change',()=>{requestId=null});
form.addEventListener('submit',async event=>{event.preventDefault();if(busy||!form.reportValidity()||!token)return;busy=true;updateButton();result.textContent='';result.classList.remove('success');requestId??=newId();const values=new FormData(form);const payload={name:String(values.get('name')||''),email:String(values.get('email')||''),subject:String(values.get('subject')||''),message:String(values.get('message')||''),website:String(values.get('website')||''),consent:values.get('consent')==='on',token,requestId};const fields=[...form.querySelectorAll('.contact-fields input,.contact-fields textarea,.contact-consent input')];fields.forEach(field=>field.disabled=true);try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||'Could not send the message. Please try again.');form.reset();requestId=null;result.classList.add('success');result.textContent='Message accepted for delivery. Reference: '+data.reference+'.';}catch(error){result.textContent=error instanceof TypeError?'Could not connect. Please try again or use the email link.':(error.message||'Could not send the message. Please try again.')}finally{fields.forEach(field=>field.disabled=false);busy=false;clearChallenge()}});
})();
